 async closeTrustedTurn(taskKey:string,rawIdentity:unknown){const guard=this.#guard(),identity=turnRuntimeIdentity(rawIdentity),route=guard.lookupTrustedTurnRoute(identity);if(!route||route.taskKey!==taskKey)throw Error('g5-authority-turn-route-mismatch');const ports=this.#ports(identity),tool=this.env.TOOL_BRIDGE_AGENT!.getByName(await toolBridgeActorName(identity.scope,identity.turnId,identity.dispatchId));const records=await Promise.all([this.#read(()=>ports.token.turnSettlement(identity.scope.tenantId,identity)),this.#read(()=>ports.money.turnSettlement(identity)),this.#read(()=>tool.turnSettlement(identity))]);try{await this.#tokenPolicy(identity);records.forEach((r,i)=>this.#quiescent(r,identity,['model','money','tool'][i],true));}catch{throw Error('g5-authority-turn-unsettled');}const task=this.ctx.storage.sql.exec<{document:string}>('SELECT document FROM g5_tasks WHERE key=?',taskKey).toArray()[0];const user=JSON.parse(String(task.document)).userId;const receipts=Object.fromEntries(await Promise.all(records.map(async(record,i)=>[['tokens','money','tools'][i],{turnKey:taskKey,turnId:identity.turnId,tenantId:identity.scope.tenantId,userId:user,closed:true,active:0,pending:0,unknown:0,receiptSha256:await turnDigest(record)}])));return guard.closeTurn(taskKey,receipts);}
 async cancelUnstartedTask(key:string){return this.#guard().cancelUnstartedTask(key);}
 async markUnknown(key:string){return this.#guard().markUnknown(key);}
 async closeAdmission(){return this.#guard().closeAdmission();}
 async snapshot(){if(!this.env.G5_WINDOW_GUARD.idFromName(G5_GLOBAL_ACTOR).equals(this.ctx.id))throw Error('g5-window-actor-scope-denied');return readG5WindowSnapshot(this.ctx.storage,g5WindowPolicy(this.env.G5_CONTROLLED_WINDOW_JSON===undefined?undefined:JSON.parse(this.env.G5_CONTROLLED_WINDOW_JSON)));}
